```hcl
resource "aws_security_group" "<example_resource_name>" {
  vpc_id = "<example_resource_id>"

  ingress {
    from_port   = 23
    to_port     = 23
    protocol    = "tcp"
    cidr_blocks = ["10.0.0.0/8"] # CRITICAL: Restricts Telnet (23); do not use 0.0.0.0/0 or ::/0
  }
}
```

